    // === нормализованный индекс (пробелы и \n → одиночный пробел) ===
    const exactTranslationsNormalized = {};
    for (const [k, v] of Object.entries(exactTranslations)) {
        const nk = k.replace(/\s+/g, ' ').trim();
        if (nk && !(nk in exactTranslationsNormalized)) {
            exactTranslationsNormalized[nk] = v;
        }
    }

    // === v6.2: индекс в нижнем регистре (для "Open Source" vs "Open source") ===
    const lowerCaseTranslations = {};
    for (const [key, value] of Object.entries(exactTranslations)) {
        if (key.includes('{0}') || key.includes(' (')) continue;
        lowerCaseTranslations[key.toLowerCase()] = value;
    }

